const FoodReviewOverlay: React.FC<FoodReviewOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10, // Unused directly, but required by schema rules
  accentColor = "#E6C98F",
  cardBaseColor = "#1A1A1C",
  foodName = "TRUFFLE RISOTTO",
  foodDescription = "CREAMY ARBORIO RICE WITH BLACK TRUFFLE",
  price = 28,
  currencySymbol = "$",
  tasteScore = 9.2,
  valueScore = 8.7,
  badgeText = "MUST TRY",
  showBadge = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animations
  const cardScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80, mass: 0.8 },
  });

  const cardOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Staggered reveals
  const getRevealOpacity = (delay: number) =>
    interpolate(frame - delay, [0, 15], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const getRevealY = (delay: number) =>
    interpolate(frame - delay, [0, 20], [20 * s, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const topRowOpacity = getRevealOpacity(10);
  const topRowY = getRevealY(10);

  const dividerProgress = spring({
    frame: frame - 20,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  const bottomRowOpacity = getRevealOpacity(25);
  const bottomRowY = getRevealY(25);

  const badgeOpacity = getRevealOpacity(35);
  const badgeScale = spring({
    frame: frame - 35,
    fps,
    config: { damping: 12, stiffness: 120 },
  });

  // Number counting animations
  const animatedTasteScore = interpolate(
    spring({ frame: frame - 30, fps, config: { damping: 15, stiffness: 60 } }),
    [0, 1],
    [0, tasteScore]
  ).toFixed(1);

  const animatedValueScore = interpolate(
    spring({ frame: frame - 35, fps, config: { damping: 15, stiffness: 60 } }),
    [0, 1],
    [0, valueScore]
  ).toFixed(1);

  const animatedPrice = interpolate(
    spring({ frame: frame - 15, fps, config: { damping: 15, stiffness: 60 } }),
    [0, 1],
    [0, price]
  ).toFixed(0);

  // Layout Dimensions
  const cardWidth = 1400 * s;
  const cardHeight = 460 * s;
  const paddingX = 70 * s;
  const paddingY = 60 * s;
  const iconSize = 130 * s;
  const smallIconSize = 100 * s;
  const dividerHeight = 160 * s;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: montserratFamily, // Base font
      }}
    >
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          backgroundColor: `${cardBaseColor}cc`, // 80% opacity
          backdropFilter: `blur(${15 * s}px)`,
          WebkitBackdropFilter: `blur(${15 * s}px)`,
          borderRadius: 30 * s,
          border: `${1 * s}px solid ${accentColor}40`,
          boxShadow: `0 ${20 * s}px ${50 * s}px rgba(0,0,0,0.5), inset 0 0 ${
            40 * s
          }px rgba(255,255,255,0.02)`,
          display: "flex",
          flexDirection: "column",
          padding: `${paddingY}px ${paddingX}px`,
          boxSizing: "border-box",
          opacity: cardOpacity,
          transform: `scale(${0.95 + cardScale * 0.05})`,
          transition: "none",
        }}
      >
        {/* Top Section */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            opacity: topRowOpacity,
            transform: `translateY(${topRowY}px)`,
            transition: "none",
            height: "50%",
            width: "100%",
          }}
        >
          {/* Main Icon */}
          <div
            style={{
              width: iconSize,
              height: iconSize,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              flexShrink: 0,
            }}
          >
            <ClocheIcon color={accentColor} size={iconSize} />
          </div>

          {/* Title & Desc */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              marginLeft: 40 * s,
              flex: 1,
              justifyContent: "center",
            }}
          >
            <div
              style={{
                fontFamily: oswaldFamily,
                fontSize: 76 * s,
                fontWeight: 500,
                color: "#FFFFFF",
                letterSpacing: 2 * s,
                lineHeight: 1.1,
                textTransform: "uppercase",
              }}
            >
              {foodName}
            </div>
            <div
              style={{
                fontSize: 24 * s,
                color: accentColor,
                opacity: 0.8,
                marginTop: 8 * s,
                letterSpacing: 1.5 * s,
                textTransform: "uppercase",
                maxWidth: "80%",
              }}
            >
              {foodDescription}
            </div>
          </div>

          {/* Vertical Divider */}
          <div
            style={{
              width: 1 * s,
              height: dividerHeight,
              backgroundColor: `${accentColor}40`,
              margin: `0 ${50 * s}px`,
            }}
          />

          {/* Price */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              justifyContent: "center",
              width: 200 * s,
            }}
          >
            <div
              style={{
                fontFamily: oswaldFamily,
                fontSize: 90 * s,
                color: accentColor,
                lineHeight: 1,
                display: "flex",
                alignItems: "baseline",
              }}
            >
              <span style={{ fontSize: 60 * s, marginRight: 5 * s }}>
                {currencySymbol}
              </span>
              {animatedPrice}
            </div>
            <div
              style={{
                fontSize: 18 * s,
                color: accentColor,
                opacity: 0.7,
                letterSpacing: 2 * s,
                marginTop: 5 * s,
                textTransform: "uppercase",
              }}
            >
              Price
            </div>
          </div>
        </div>

        {/* Horizontal Divider */}
        <div
          style={{
            width: "100%",
            height: 1 * s,
            backgroundColor: `${accentColor}20`,
            margin: `${30 * s}px 0`,
            position: "relative",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              height: "100%",
              width: "100%",
              backgroundColor: `${accentColor}60`,
              transform: `scaleX(${dividerProgress})`,
              transformOrigin: "left",
              transition: "none",
            }}
          />
        </div>

        {/* Bottom Section */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            opacity: bottomRowOpacity,
            transform: `translateY(${bottomRowY}px)`,
            transition: "none",
            height: "50%",
            width: "100%",
          }}
        >
          {/* Taste Score */}
          <div style={{ display: "flex", flexDirection: "row", alignItems: "center" }}>
            <StarIcon color={accentColor} size={smallIconSize} />
            <div style={{ marginLeft: 25 * s }}>
              <div
                style={{
                  fontFamily: oswaldFamily,
                  fontSize: 70 * s,
                  color: "#FFFFFF",
                  lineHeight: 1,
                }}
              >
                {animatedTasteScore}
              </div>
              <div
                style={{
                  fontSize: 16 * s,
                  color: accentColor,
                  opacity: 0.7,
                  letterSpacing: 1.5 * s,
                  marginTop: 5 * s,
                  textTransform: "uppercase",
                }}
              >
                Taste Score
              </div>
            </div>
          </div>

          <div
            style={{
              width: 1 * s,
              height: 70 * s,
              backgroundColor: `${accentColor}30`,
              margin: `0 ${40 * s}px`,
            }}
          />

          {/* Value Score */}
          <div style={{ display: "flex", flexDirection: "row", alignItems: "center" }}>
            <TagIcon color={accentColor} size={smallIconSize} />
            <div style={{ marginLeft: 25 * s }}>
              <div
                style={{
                  fontFamily: oswaldFamily,
                  fontSize: 70 * s,
                  color: "#FFFFFF",
                  lineHeight: 1,
                }}
              >
                {animatedValueScore}
              </div>
              <div
                style={{
                  fontSize: 16 * s,
                  color: accentColor,
                  opacity: 0.7,
                  letterSpacing: 1.5 * s,
                  marginTop: 5 * s,
                  textTransform: "uppercase",
                }}
              >
                Value Score
              </div>
            </div>
          </div>

          <div style={{ flex: 1 }} />

          {/* Badge */}
          {showBadge && (
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                border: `${2 * s}px solid ${accentColor}`,
                borderRadius: 20 * s,
                padding: `${15 * s}px ${35 * s}px`,
                backgroundColor: `${accentColor}10`, // slight fill
                opacity: badgeOpacity,
                transform: `scale(${badgeScale})`,
                transition: "none",
                boxShadow: `0 0 ${30 * s}px ${accentColor}20`,
              }}
            >
              <div style={{ marginRight: 15 * s, marginTop: -5 * s }}>
                <CrownIcon color={accentColor} size={50 * s} />
              </div>
              <div
                style={{
                  fontFamily: oswaldFamily,
                  fontSize: 45 * s,
                  color: accentColor,
                  textTransform: "uppercase",
                  letterSpacing: 2 * s,
                  lineHeight: 1,
                }}
              >
                {badgeText}
              </div>
            </div>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FoodReviewOverlay;